<?php include __DIR__.'/start.php';?><section class="narrow"><p class="eyebrow"><?=me(__('manor.begin_your_occasion'))?></p><h1><?=me(__('manor.make_an_enquiry'))?></h1><p><?=me(__('manor.enquiry_no_confirmation'))?></p><?php if(!$settings['flags']['enquiries']||!$settings['flags']['venues']):?><p><?=me(__('manor.enquiries_are_currently_closed'))?></p><?php else:?><form method="post" action="/manor/enquire"><?=csrf()?><input type="hidden" name="consent_version" value="<?=me(\App\Manor\Content::consentVersion())?>"><label><?=me(__('manor.space'))?><select name="unit_id" data-venue-select required><?php foreach($units as $unit):try{\App\Manor\Settings::mode($unit['mode']);}catch(\DomainException){continue;}if(in_array($unit['mode'],['BUILDING','FLOOR'],true)||!\App\Manor\Inventory::enabled($unit['id']))continue;$d=json_decode($unit['data'],true);$modes=$unit['mode']==='ACCOMMODATION_UNIT'?['night']:($d['duration_modes']??['hour','day']);?><option value="<?=me($unit['id'])?>" data-modes="<?=me(implode(',',$modes))?>" <?=($_GET['unit']??'')===$unit['id']?'selected':''?>><?=me(\App\Engine\Locale::getLocale()==='ar'?($d['name_ar']??$unit['name']):$unit['name'])?></option><?php endforeach?></select></label><label><?=me(__('manor.duration_mode'))?><select name="duration_mode" data-duration-select><option value="hour"><?=me(__('manor.duration_hour'))?></option><option value="day"><?=me(__('manor.duration_day'))?></option><option value="night"><?=me(__('manor.duration_night'))?></option></select></label><div class="grid" data-duration-panel="hour"><?=field('start',__('manor.start_europe_london'),'','datetime-local')?><?=field('end',__('manor.end_europe_london'),'','datetime-local')?></div><div data-duration-panel="day" hidden><?=field('hire_date',__('manor.full_day_hire_date'),'','date',false)?></div><div class="grid" data-duration-panel="night" hidden><?=field('check_in_date',__('manor.check_in_date'),'','date',false)?><?=field('check_out_date',__('manor.check_out_date'),'','date',false)?></div><?=field('guests',__('manor.expected_attendance'),'1','number')?><?=field('name',__('manor.your_name'))?><?=field('email',__('manor.email_address'),'','email')?><?=field('phone',__('manor.phone_number'),'','tel',false)?><label><?=me(__('manor.event_details'))?><textarea name="details" maxlength="10000" required></textarea></label><details><summary><?=me(__('manor.privacy_notice_booking_terms'))?></summary><p><?=me($settings['privacy'])?></p><p><?=me($settings['terms'])?></p></details><label class="check"><input type="checkbox" name="consent" value="1" required><?=me($settings['consent'])?></label><label class="honeypot" aria-hidden="true"><?=me(__('manor.leave_blank'))?><input name="website" tabindex="-1" autocomplete="off"></label><button><?=me(__('manor.create_draft_enquiry'))?></button></form><script src="/manor/enquiry.js" defer></script><?php endif?><p><a href="/manor/recover"><?=me(__('manor.recover_access'))?></a></p></section><?php include __DIR__.'/end.php';?>
